static std::array<S,2> center_inverse(const curved::Record&r,Q x,Q y,double eps){Q X=x,Y=y;for(int i=0;i<12;i++){auto p=mf::original_at(r,S(X),S(Y),eps);Q det=p.F[0].n*p.F[3].n-p.F[1].n*p.F[2].n,dx=p.position[0].n-x,dy=p.position[1].n-y,a=(p.F[3].n*dx-p.F[1].n*dy)/det,b=(-p.F[2].n*dx+p.F[0].n*dy)/det;X-=a;Y-=b;if(std::max(fabsq(a),fabsq(b))<1e-29Q)break;}return {S(X),S(Y)};}
